package model

import "time"

// Output represents the complete output structure
type Output struct {
	Version     string    `json:"version"`
	GeneratedAt time.Time `json:"generated_at"`
	Sessions    []Session `json:"sessions"`
}

// Session represents a unified agent session
type Session struct {
	AgentType string          `json:"agent_type"` // "claude" or "goose"
	SessionID string          `json:"session_id"`
	CreatedAt time.Time       `json:"created_at"`
	UpdatedAt time.Time       `json:"updated_at"`
	Metadata  SessionMetadata `json:"metadata"`
	Messages  []Message       `json:"messages"`
	Subagents []Subagent      `json:"subagents,omitempty"`
}

// SessionMetadata contains session-level metadata
type SessionMetadata struct {
	WorkingDir string            `json:"working_dir,omitempty"`
	GitBranch  string            `json:"git_branch,omitempty"`
	Model      string            `json:"model,omitempty"`
	Provider   string            `json:"provider,omitempty"`
	Name       string            `json:"name,omitempty"`
	Extra      map[string]string `json:"extra,omitempty"`
}

// Message represents a single message in a conversation
type Message struct {
	UUID       string          `json:"uuid"`
	ParentUUID string          `json:"parent_uuid,omitempty"`
	Timestamp  time.Time       `json:"timestamp"`
	Role       string          `json:"role"` // "user" or "assistant"
	Content    []ContentBlock  `json:"content"`
	Metadata   MessageMetadata `json:"metadata"`
}

// ContentBlock represents a piece of content (text, tool use, or tool result)
type ContentBlock struct {
	Type        string         `json:"type"` // "text", "tool_use", "tool_result"
	Text        string         `json:"text,omitempty"`
	ToolName    string         `json:"tool_name,omitempty"`
	ToolInput   map[string]any `json:"tool_input,omitempty"`
	ToolUseID   string         `json:"tool_use_id,omitempty"`
	ToolContent string         `json:"tool_content,omitempty"`
}

// MessageMetadata contains message-level metadata
type MessageMetadata struct {
	IsSidechain bool              `json:"is_sidechain,omitempty"`
	AgentID     string            `json:"agent_id,omitempty"`
	Tokens      *TokenUsage       `json:"tokens"`
	Model       string            `json:"model,omitempty"`
	RequestID   string            `json:"request_id,omitempty"`
	Extra       map[string]string `json:"extra,omitempty"`
}

// TokenUsage represents token usage statistics
type TokenUsage struct {
	InputTokens  int `json:"input_tokens,omitempty"`
	OutputTokens int `json:"output_tokens,omitempty"`
	TotalTokens  int `json:"total_tokens,omitempty"`
}

// Subagent represents a subagent conversation
type Subagent struct {
	AgentID  string    `json:"agent_id"`
	Slug     string    `json:"slug,omitempty"`
	Messages []Message `json:"messages"`
}

package filter

import (
	"testing"
	"time"

	"github.com/block/braindump/internal/model"
)

func TestApply(t *testing.T) {
	now := time.Now()
	yesterday := now.Add(-24 * time.Hour)
	tomorrow := now.Add(24 * time.Hour)

	sessions := []model.Session{
		{
			AgentType: "claude",
			SessionID: "session-1",
			CreatedAt: now,
		},
		{
			AgentType: "goose",
			SessionID: "session-2",
			CreatedAt: yesterday,
		},
		{
			AgentType: "claude",
			SessionID: "session-3",
			CreatedAt: tomorrow,
		},
	}

	tests := []struct {
		name     string
		opts     Options
		expected int
	}{
		{
			name:     "no filters",
			opts:     Options{},
			expected: 3,
		},
		{
			name: "filter by agent type - claude",
			opts: Options{
				AgentType: "claude",
			},
			expected: 2,
		},
		{
			name: "filter by agent type - goose",
			opts: Options{
				AgentType: "goose",
			},
			expected: 1,
		},
		{
			name: "filter by session ID",
			opts: Options{
				SessionID: "session-2",
			},
			expected: 1,
		},
		{
			name: "filter by since date",
			opts: Options{
				Since: now.Add(-1 * time.Hour),
			},
			expected: 2, // now and tomorrow
		},
		{
			name: "filter by until date",
			opts: Options{
				Until: now.Add(1 * time.Hour),
			},
			expected: 2, // yesterday and now
		},
		{
			name: "combined filters",
			opts: Options{
				AgentType: "claude",
				Since:     yesterday,
				Until:     now.Add(1 * time.Hour),
			},
			expected: 1, // only session-1
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := Apply(sessions, tt.opts)

			if len(result) != tt.expected {
				t.Errorf("Expected %d sessions, got %d", tt.expected, len(result))
			}
		})
	}
}

func TestShouldInclude(t *testing.T) {
	now := time.Now()
	session := model.Session{
		AgentType: "claude",
		SessionID: "test-session",
		CreatedAt: now,
	}

	tests := []struct {
		name     string
		opts     Options
		expected bool
	}{
		{
			name:     "no filters - include",
			opts:     Options{},
			expected: true,
		},
		{
			name: "matching agent type",
			opts: Options{
				AgentType: "claude",
			},
			expected: true,
		},
		{
			name: "non-matching agent type",
			opts: Options{
				AgentType: "goose",
			},
			expected: false,
		},
		{
			name: "matching session ID",
			opts: Options{
				SessionID: "test-session",
			},
			expected: true,
		},
		{
			name: "non-matching session ID",
			opts: Options{
				SessionID: "other-session",
			},
			expected: false,
		},
		{
			name: "since before created - include",
			opts: Options{
				Since: now.Add(-1 * time.Hour),
			},
			expected: true,
		},
		{
			name: "since after created - exclude",
			opts: Options{
				Since: now.Add(1 * time.Hour),
			},
			expected: false,
		},
		{
			name: "until after created - include",
			opts: Options{
				Until: now.Add(1 * time.Hour),
			},
			expected: true,
		},
		{
			name: "until before created - exclude",
			opts: Options{
				Until: now.Add(-1 * time.Hour),
			},
			expected: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := shouldInclude(session, tt.opts)

			if result != tt.expected {
				t.Errorf("Expected %v, got %v", tt.expected, result)
			}
		})
	}
}

package goose

import (
	"testing"

	"github.com/block/braindump/internal/model"
)

func TestParseContent(t *testing.T) {
	tests := []struct {
		name     string
		json     string
		expected int // expected number of content blocks
	}{
		{
			name:     "simple string",
			json:     `"Hello, world!"`,
			expected: 1,
		},
		{
			name: "array of blocks",
			json: `[
				{"type": "text", "text": "Hello"},
				{"type": "text", "text": "World"}
			]`,
			expected: 2,
		},
		{
			name:     "single block object",
			json:     `{"type": "text", "text": "Hello"}`,
			expected: 1,
		},
		{
			name:     "invalid json",
			json:     `{invalid}`,
			expected: 0,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := parseContent(tt.json)

			if len(result) != tt.expected {
				t.Errorf("Expected %d blocks, got %d", tt.expected, len(result))
			}
		})
	}
}

func TestParseContentBlock(t *testing.T) {
	tests := []struct {
		name     string
		block    map[string]any
		expected *model.ContentBlock
	}{
		{
			name: "text block",
			block: map[string]any{
				"type": "text",
				"text": "Hello",
			},
			expected: &model.ContentBlock{
				Type: "text",
				Text: "Hello",
			},
		},
		{
			name: "tool use block",
			block: map[string]any{
				"type": "tool_use",
				"name": "bash",
				"id":   "tool-456",
				"input": map[string]any{
					"command": "ls -la",
				},
			},
			expected: &model.ContentBlock{
				Type:      "tool_use",
				ToolName:  "bash",
				ToolUseID: "tool-456",
				ToolInput: map[string]any{
					"command": "ls -la",
				},
			},
		},
		{
			name: "tool result block",
			block: map[string]any{
				"type":        "tool_result",
				"tool_use_id": "tool-456",
				"content":     "file1.txt\nfile2.txt",
			},
			expected: &model.ContentBlock{
				Type:        "tool_result",
				ToolUseID:   "tool-456",
				ToolContent: "file1.txt\nfile2.txt",
			},
		},
		{
			name: "unknown type with text",
			block: map[string]any{
				"type": "custom",
				"text": "Custom content",
			},
			expected: &model.ContentBlock{
				Type: "custom",
				Text: "Custom content",
			},
		},
		{
			name: "unknown type without text",
			block: map[string]any{
				"type": "unknown",
			},
			expected: nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result := parseContentBlock(tt.block)

			if tt.expected == nil {
				if result != nil {
					t.Errorf("Expected nil, got %+v", result)
				}
				return
			}

			if result == nil {
				t.Fatal("parseContentBlock returned nil")
			}

			if result.Type != tt.expected.Type {
				t.Errorf("Type: got %q, want %q", result.Type, tt.expected.Type)
			}

			if result.Text != tt.expected.Text {
				t.Errorf("Text: got %q, want %q", result.Text, tt.expected.Text)
			}

			if result.ToolName != tt.expected.ToolName {
				t.Errorf("ToolName: got %q, want %q", result.ToolName, tt.expected.ToolName)
			}
		})
	}
}

