const Version = "1.0.0"

// Writer handles writing output in JSON format
type Writer struct {
	writer io.Writer
	pretty bool
}

// NewWriter creates a new output writer
func NewWriter(w io.Writer, pretty bool) *Writer {
	return &Writer{
		writer: w,
		pretty: pretty,
	}
}

// Write writes sessions to output
func (w *Writer) Write(sessions []model.Session) error {
	output := model.Output{
		Version:     Version,
		GeneratedAt: time.Now(),
		Sessions:    sessions,
	}

	var data []byte
	var err error

	if w.pretty {
		data, err = json.MarshalIndent(output, "", "  ")
	} else {
		data, err = json.Marshal(output)
	}

	if err != nil {
		return err
	}

	_, err = w.writer.Write(data)
	if err != nil {
		return err
	}

	// Add newline at end
	_, err = w.writer.Write([]byte("\n"))
	return err
}

package goose

import (
	"encoding/json"

	"github.com/block/braindump/internal/model"
)

// parseContent parses Goose content JSON into content blocks
func parseContent(contentJSON string) []model.ContentBlock {
	var content any
	if err := json.Unmarshal([]byte(contentJSON), &content); err != nil {
		return nil
	}

	var blocks []model.ContentBlock

	// Handle different content formats
	switch v := content.(type) {
	case string:
		// Simple string content
		blocks = append(blocks, model.ContentBlock{
			Type: "text",
			Text: v,
		})

	case []any:
		// Array of content blocks
		for _, item := range v {
			if block, isBlock := item.(map[string]any); isBlock {
				contentBlock := parseContentBlock(block)
				if contentBlock != nil {
					blocks = append(blocks, *contentBlock)
				}
			} else if str, isStr := item.(string); isStr {
				blocks = append(blocks, model.ContentBlock{
					Type: "text",
					Text: str,
				})
			}
		}

	case map[string]any:
		// Single content block
		contentBlock := parseContentBlock(v)
		if contentBlock != nil {
			blocks = append(blocks, *contentBlock)
		}
	}

	return blocks
}

// parseContentBlock parses a single content block
func parseContentBlock(block map[string]any) *model.ContentBlock {
	blockType, _ := block["type"].(string)

	switch blockType {
	case "text":
		text, _ := block["text"].(string)
		return &model.ContentBlock{
			Type: "text",
			Text: text,
		}

	case "tool_use":
		toolName, _ := block["name"].(string)
		toolUseID, _ := block["id"].(string)
		toolInput, _ := block["input"].(map[string]any)

		return &model.ContentBlock{
			Type:      "tool_use",
			ToolName:  toolName,
			ToolUseID: toolUseID,
			ToolInput: toolInput,
		}

	case "tool_result":
		toolUseID, _ := block["tool_use_id"].(string)

		// Content can be string or nested
		var toolContent string
		if contentStr, ok := block["content"].(string); ok {
			toolContent = contentStr
		}

		return &model.ContentBlock{
			Type:        "tool_result",
			ToolUseID:   toolUseID,
			ToolContent: toolContent,
		}

	default:
		// For unknown types, try to extract text field
		if text, ok := block["text"].(string); ok {
			return &model.ContentBlock{
				Type: blockType,
				Text: text,
			}
		}
	}

	return nil
}

package claude

import (
	"strings"
	"time"

	"github.com/block/braindump/internal/model"
)

// parseMessage parses a Claude message from raw JSON
func parseMessage(raw map[string]any) *model.Message {
	uuid, _ := raw["uuid"].(string)
	parentUUID, _ := raw["parentUuid"].(string)

	var timestamp time.Time
	if tsStr, ok := raw["timestamp"].(string); ok {
		timestamp, _ = time.Parse(time.RFC3339, tsStr)
	}

	// Extract message content
	messageData, ok := raw["message"].(map[string]any)
	if !ok {
		return nil
	}

	role, _ := messageData["role"].(string)
	if role == "" {
		return nil
	}

	// Parse content blocks
	var contentBlocks []model.ContentBlock

	// Handle both string content and array content
	if contentStr, isString := messageData["content"].(string); isString {
		contentBlocks = []model.ContentBlock{
			{
				Type: "text",
				Text: contentStr,
			},
		}
	} else if contentArr, isArray := messageData["content"].([]any); isArray {
		for _, item := range contentArr {
			if block, isBlock := item.(map[string]any); isBlock {
				contentBlock := parseContentBlock(block)
				if contentBlock != nil {
					contentBlocks = append(contentBlocks, *contentBlock)
				}
			}
		}
	}

	// Build metadata
	metadata := model.MessageMetadata{}

	if isSidechain, hasSidechain := raw["isSidechain"].(bool); hasSidechain {
		metadata.IsSidechain = isSidechain
	}

	if agentID, hasAgentID := raw["agentId"].(string); hasAgentID {
		metadata.AgentID = agentID
	}

	if requestID, hasRequestID := raw["requestId"].(string); hasRequestID {
		metadata.RequestID = requestID
	}

	// Extract model from message
	if modelStr, hasModel := messageData["model"].(string); hasModel {
		metadata.Model = modelStr
	}

	// Extract token usage
	if usage, hasUsage := messageData["usage"].(map[string]any); hasUsage {
		metadata.Tokens = parseTokenUsage(usage)
	}

	return &model.Message{
		UUID:       uuid,
		ParentUUID: parentUUID,
		Timestamp:  timestamp,
		Role:       role,
		Content:    contentBlocks,
		Metadata:   metadata,
	}
}

// parseContentBlock parses a content block
func parseContentBlock(block map[string]any) *model.ContentBlock {
	blockType, _ := block["type"].(string)

	switch blockType {
	case "text":
		text, _ := block["text"].(string)
		return &model.ContentBlock{
			Type: "text",
			Text: text,
		}

	case "tool_use":
		toolName, _ := block["name"].(string)
		toolUseID, _ := block["id"].(string)
		toolInput, _ := block["input"].(map[string]any)

		return &model.ContentBlock{
			Type:      "tool_use",
			ToolName:  toolName,
			ToolUseID: toolUseID,
			ToolInput: toolInput,
		}

	case "tool_result":
		toolUseID, _ := block["tool_use_id"].(string)
		toolContent := extractToolContent(block["content"])

		return &model.ContentBlock{
			Type:        "tool_result",
			ToolUseID:   toolUseID,
			ToolContent: toolContent,
		}
	}

	return nil
}

// extractToolContent extracts content from tool result, handling both string and array formats
func extractToolContent(content any) string {
	// Content can be string or array
	if contentStr, isString := content.(string); isString {
		return contentStr
	}

	contentArr, isArray := content.([]any)
	if !isArray {
		return ""
	}

	// Join array elements
	var builder strings.Builder
	for i, item := range contentArr {
		if i > 0 {
			builder.WriteString("\n")
		}

		if itemMap, isMap := item.(map[string]any); isMap {
			if text, hasText := itemMap["text"].(string); hasText {
				builder.WriteString(text)
			}
		} else if str, isStr := item.(string); isStr {
			builder.WriteString(str)
		}
	}

	return builder.String()
}

// parseTokenUsage parses token usage from Claude message
func parseTokenUsage(usage map[string]any) *model.TokenUsage {
	tokens := &model.TokenUsage{}

	if inputTokens, ok := usage["input_tokens"].(float64); ok {
		tokens.InputTokens = int(inputTokens)
	}

	if outputTokens, ok := usage["output_tokens"].(float64); ok {
		tokens.OutputTokens = int(outputTokens)
	}

	// Calculate total
	tokens.TotalTokens = tokens.InputTokens + tokens.OutputTokens

	return tokens
}

package main

import (
	"fmt"
	"os"
	"time"

	"github.com/block/braindump/internal/claude"
	"github.com/block/braindump/internal/filter"
	"github.com/block/braindump/internal/goose"
	"github.com/block/braindump/internal/model"
	"github.com/block/braindump/internal/output"
	"github.com/spf13/cobra"
)

var (
	agentType string
	sessionID string
	since     string
	until     string
	outFile   string
	pretty    bool
	summary   bool
)

func main() {
	var rootCmd = &cobra.Command{
		Use:   "braindump",
		Short: "Dump agent session histories to JSON",
		Long: `braindump reads Claude Code and Goose AI agent session histories
and outputs them in a unified JSON format.`,
		RunE: run,
	}

	rootCmd.Flags().StringVar(&agentType, "agent", "", "Filter by agent type (claude, goose)")
	rootCmd.Flags().StringVar(&sessionID, "session-id", "", "Filter by specific session ID")
	rootCmd.Flags().StringVar(&since, "since", "", "Filter sessions since timestamp (RFC3339)")
	rootCmd.Flags().StringVar(&until, "until", "", "Filter sessions until timestamp (RFC3339)")
	rootCmd.Flags().StringVarP(&outFile, "output", "o", "", "Output file (default: stdout)")
	rootCmd.Flags().BoolVar(&pretty, "pretty", false, "Pretty-print JSON output")
	rootCmd.Flags().BoolVar(&summary, "summary", false, "Output human-readable summary instead of JSON")

	if err := rootCmd.Execute(); err != nil {
		os.Exit(1)
	}
}

func run(cmd *cobra.Command, args []string) error {
	// Parse time filters
	var sinceTime, untilTime time.Time
	var err error

	if since != "" {
		sinceTime, err = time.Parse(time.RFC3339, since)
		if err != nil {
			return fmt.Errorf("invalid --since timestamp: %w", err)
		}
	}

	if until != "" {
		untilTime, err = time.Parse(time.RFC3339, until)
		if err != nil {
			return fmt.Errorf("invalid --until timestamp: %w", err)
		}
	}

	// Read sessions from all sources
	var allSessions []model.Session

	// Read Claude sessions (if not filtered to goose only)
	if agentType == "" || agentType == "claude" {
		claudeReader, err := claude.NewReader()
		if err != nil {
			return fmt.Errorf("failed to create Claude reader: %w", err)
		}

		claudeSessions, err := claudeReader.ReadSessions()
		if err != nil {
			return fmt.Errorf("failed to read Claude sessions: %w", err)
		}

		allSessions = append(allSessions, claudeSessions...)
	}

	// Read Goose sessions (if not filtered to claude only)
	if agentType == "" || agentType == "goose" {
		gooseReader, err := goose.NewReader()
		if err != nil {
			return fmt.Errorf("failed to create Goose reader: %w", err)
		}

		gooseSessions, err := gooseReader.ReadSessions()
		if err != nil {
			return fmt.Errorf("failed to read Goose sessions: %w", err)
		}

		allSessions = append(allSessions, gooseSessions...)
	}

	// Apply filters
	filterOpts := filter.Options{
		AgentType: agentType,
		SessionID: sessionID,
		Since:     sinceTime,
		Until:     untilTime,
	}

	filteredSessions := filter.Apply(allSessions, filterOpts)

	// Write output
	var writer *os.File
	if outFile != "" {
		writer, err = os.Create(outFile)
		if err != nil {
			return fmt.Errorf("failed to create output file: %w", err)
		}
		defer writer.Close()
	} else {
		writer = os.Stdout
	}

	// Choose output format
	if summary {
		summaryWriter := output.NewSummaryWriter(writer)
		if err := summaryWriter.Write(filteredSessions); err != nil {
			return fmt.Errorf("failed to write summary: %w", err)
		}
	} else {
		outputWriter := output.NewWriter(writer, pretty)
		if err := outputWriter.Write(filteredSessions); err != nil {
			return fmt.Errorf("failed to write output: %w", err)
		}
	}

	return nil
}

package output

import (
	"fmt"
	"io"
	"strings"

	"github.com/block/braindump/internal/model"
)

// SummaryWriter handles writing human-readable summaries
type SummaryWriter struct {
	writer io.Writer
}

// NewSummaryWriter creates a new summary writer
func NewSummaryWriter(w io.Writer) *SummaryWriter {
	return &SummaryWriter{writer: w}
}

// Write writes session summaries to output
func (w *SummaryWriter) Write(sessions []model.Session) error {
	if len(sessions) == 0 {
		_, err := fmt.Fprintln(w.writer, "No sessions found.")
		return err
	}

	for i, session := range sessions {
		if i > 0 {
			_, err := fmt.Fprintln(w.writer, "\n"+strings.Repeat("=", 80))
			if err != nil {
				return err
			}
		}

		if err := w.writeSessionSummary(session); err != nil {
			return err
		}
	}

	return nil
}

// writeSessionSummary writes a summary for a single session
func (w *SummaryWriter) writeSessionSummary(session model.Session) error {
	// Header
	_, err := fmt.Fprintf(w.writer, "\n📋 Session: %s\n", session.SessionID)
	if err != nil {
		return err
	}

	_, err = fmt.Fprintf(w.writer, "   Agent: %s\n", session.AgentType)
	if err != nil {
		return err
	}

	_, err = fmt.Fprintf(w.writer, "   Created: %s\n", session.CreatedAt.Format("2006-01-02 15:04:05"))
	if err != nil {
		return err
	}

	if session.Metadata.WorkingDir != "" {
		_, err = fmt.Fprintf(w.writer, "   Working Dir: %s\n", session.Metadata.WorkingDir)
		if err != nil {
			return err
		}
	}

	if session.Metadata.Model != "" {
		_, err = fmt.Fprintf(w.writer, "   Model: %s\n", session.Metadata.Model)
		if err != nil {
			return err
		}
	}

	// Find key messages
	firstUserMsg := findFirstUserMessage(session.Messages)
	lastUserMsg := findLastUserMessage(session.Messages)
	lastAgentMsgs := findLastAgentMessages(session.Messages, 2)

	// Initial user prompt
	if firstUserMsg != nil {
		_, err = fmt.Fprintf(w.writer, "\n🚀 Initial User Prompt:\n")
		if err != nil {
			return err
		}

		content := extractMessageContent(firstUserMsg)
		wrapped := wrapText(content, 76)
		_, err = fmt.Fprintf(w.writer, "   %s\n", strings.ReplaceAll(wrapped, "\n", "\n   "))
		if err != nil {
			return err
		}
	}

	// Last user prompt (if different from first)
	if lastUserMsg != nil && (firstUserMsg == nil || lastUserMsg.UUID != firstUserMsg.UUID) {
		_, err = fmt.Fprintf(w.writer, "\n💬 Last User Prompt:\n")
		if err != nil {
			return err
		}

		content := extractMessageContent(lastUserMsg)
		wrapped := wrapText(content, 76)
		_, err = fmt.Fprintf(w.writer, "   %s\n", strings.ReplaceAll(wrapped, "\n", "\n   "))
		if err != nil {
			return err
		}
	}

	// Last agent messages
	if len(lastAgentMsgs) > 0 {
		_, err = fmt.Fprintf(w.writer, "\n🤖 Last %d Agent Message(s):\n", len(lastAgentMsgs))
		if err != nil {
			return err
		}

		for i, msg := range lastAgentMsgs {
			content := extractMessageContent(&msg)
			if content == "" {
				content = "[Tool use or non-text content]"
			}

			wrapped := wrapText(content, 74)
			_, err = fmt.Fprintf(w.writer, "\n   [%d] %s\n", i+1, strings.ReplaceAll(wrapped, "\n", "\n       "))
			if err != nil {
				return err
			}
		}
	}

	// Statistics
	userCount := countMessagesByRole(session.Messages, "user")
	assistantCount := countMessagesByRole(session.Messages, "assistant")

	_, err = fmt.Fprintf(w.writer, "\n📊 Statistics:\n")
	if err != nil {
		return err
	}

	_, err = fmt.Fprintf(w.writer, "   Total Messages: %d (User: %d, Agent: %d)\n", len(session.Messages), userCount, assistantCount)
	if err != nil {
		return err
	}

	if len(session.Subagents) > 0 {
		_, err = fmt.Fprintf(w.writer, "   Subagents: %d\n", len(session.Subagents))
		if err != nil {
			return err
		}
	}

	return nil
}

// findFirstUserMessage finds the first user message in the session
func findFirstUserMessage(messages []model.Message) *model.Message {
	for i := range messages {
		if messages[i].Role == "user" {
			return &messages[i]
		}
	}
	return nil
}

// findLastUserMessage finds the last user message in the session
func findLastUserMessage(messages []model.Message) *model.Message {
	for i := len(messages) - 1; i >= 0; i-- {
		if messages[i].Role == "user" {
			return &messages[i]
		}
	}
	return nil
}

// findLastAgentMessages finds the last N assistant messages
func findLastAgentMessages(messages []model.Message, count int) []model.Message {
	var result []model.Message

	for i := len(messages) - 1; i >= 0 && len(result) < count; i-- {
		if messages[i].Role == "assistant" {
			result = append([]model.Message{messages[i]}, result...)
		}
	}

	return result
}

// extractMessageContent extracts text content from a message
func extractMessageContent(msg *model.Message) string {
	var parts []string

	for _, block := range msg.Content {
		switch block.Type {
		case "text":
			if block.Text != "" {
				parts = append(parts, block.Text)
			}
		case "tool_use":
			// Skip tool use in summary
		case "tool_result":
			// Skip tool results in summary
		}
	}

	return strings.Join(parts, " ")
}

// countMessagesByRole counts messages by role
func countMessagesByRole(messages []model.Message, role string) int {
	count := 0
	for _, msg := range messages {
		if msg.Role == role {
			count++
		}
	}
	return count
}

// wrapText wraps text to a maximum width
func wrapText(text string, width int) string {
	if len(text) <= width {
		return text
	}

	var result strings.Builder
	words := strings.Fields(text)
	if len(words) == 0 {
		return text
	}

	currentLine := words[0]

	for _, word := range words[1:] {
		if len(currentLine)+1+len(word) <= width {
			currentLine += " " + word
		} else {
			result.WriteString(currentLine)
			result.WriteString("\n")
			currentLine = word
		}
	}

	result.WriteString(currentLine)
	return result.String()
}

package goose

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"github.com/block/braindump/internal/model"
	_ "modernc.org/sqlite" // Import sqlite driver for database/sql
)

// Reader handles reading Goose sessions from SQLite
type Reader struct {
	homeDir string
}

// NewReader creates a new Goose reader
func NewReader() (*Reader, error) {
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return nil, fmt.Errorf("failed to get home directory: %w", err)
	}
	return &Reader{homeDir: homeDir}, nil
}

// ReadSessions reads all Goose sessions from the SQLite database
func (r *Reader) ReadSessions() ([]model.Session, error) {
	dbPath := filepath.Join(r.homeDir, ".local", "share", "goose", "sessions", "sessions.db")

	// Check if database exists
	if _, err := os.Stat(dbPath); os.IsNotExist(err) {
		return []model.Session{}, nil // No Goose sessions
	}

	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		return nil, fmt.Errorf("failed to open database: %w", err)
	}
	defer db.Close()

	// Query sessions
	sessionsQuery := `
		SELECT id, name, description, user_set_name, session_type, working_dir,
		       created_at, updated_at, extension_data, provider_name, model_config_json
		FROM sessions
		ORDER BY created_at DESC
	`

	ctx := context.Background()
	rows, err := db.QueryContext(ctx, sessionsQuery)
	if err != nil {
		return nil, fmt.Errorf("failed to query sessions: %w", err)
	}
	defer rows.Close()

	var sessions []model.Session

	for rows.Next() {
		var (
			id              int
			name            sql.NullString
			description     sql.NullString
			userSetName     sql.NullString
			sessionType     sql.NullString
			workingDir      sql.NullString
			createdAt       sql.NullString
			updatedAt       sql.NullString
			extensionData   sql.NullString
			providerName    sql.NullString
			modelConfigJSON sql.NullString
		)

		err := rows.Scan(&id, &name, &description, &userSetName, &sessionType,
			&workingDir, &createdAt, &updatedAt, &extensionData, &providerName, &modelConfigJSON)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to scan session row: %v\n", err)
			continue
		}

		// Parse timestamps
		createdTime, _ := time.Parse(time.RFC3339, createdAt.String)
		updatedTime, _ := time.Parse(time.RFC3339, updatedAt.String)

		// Parse model config
		var modelConfig map[string]any
		if modelConfigJSON.Valid && modelConfigJSON.String != "" {
			_ = json.Unmarshal([]byte(modelConfigJSON.String), &modelConfig)
		}

		// Extract model name
		modelName := ""
		if modelConfig != nil {
			if model, ok := modelConfig["model"].(string); ok {
				modelName = model
			}
		}

		// Build metadata
		metadata := model.SessionMetadata{
			WorkingDir: workingDir.String,
			Provider:   providerName.String,
			Model:      modelName,
			Name:       name.String,
		}

		// Add extra metadata
		metadata.Extra = make(map[string]string)
		if userSetName.Valid {
			metadata.Extra["user_set_name"] = userSetName.String
		}
		if sessionType.Valid {
			metadata.Extra["session_type"] = sessionType.String
		}
		if description.Valid {
			metadata.Extra["description"] = description.String
		}

		// Read messages for this session
		messages, err := r.readMessages(db, id)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to read messages for session %d: %v\n", id, err)
			continue
		}

		sessions = append(sessions, model.Session{
			AgentType: "goose",
			SessionID: fmt.Sprintf("%d", id),
			CreatedAt: createdTime,
			UpdatedAt: updatedTime,
			Metadata:  metadata,
			Messages:  messages,
		})
	}

	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("error iterating sessions: %w", err)
	}

	return sessions, nil
}

// readMessages reads messages for a specific session
func (r *Reader) readMessages(db *sql.DB, sessionID int) ([]model.Message, error) {
	messagesQuery := `
		SELECT id, message_id, role, content_json, created_timestamp, tokens, metadata_json
		FROM messages
		WHERE session_id = ?
		ORDER BY created_timestamp ASC
	`

	ctx := context.Background()
	rows, err := db.QueryContext(ctx, messagesQuery, sessionID)
	if err != nil {
		return nil, fmt.Errorf("failed to query messages: %w", err)
	}
	defer rows.Close()

	var messages []model.Message

	for rows.Next() {
		var (
			id               int
			messageID        sql.NullString
			role             string
			contentJSON      sql.NullString
			createdTimestamp sql.NullString
			tokens           sql.NullInt64
			metadataJSON     sql.NullString
		)

		err := rows.Scan(&id, &messageID, &role, &contentJSON, &createdTimestamp, &tokens, &metadataJSON)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Warning: failed to scan message row: %v\n", err)
			continue
		}

		// Parse timestamp
		timestamp, _ := time.Parse(time.RFC3339, createdTimestamp.String)

		// Parse content
		var contentBlocks []model.ContentBlock
		if contentJSON.Valid && contentJSON.String != "" {
			contentBlocks = parseContent(contentJSON.String)
		}

		// Build metadata
		metadata := model.MessageMetadata{}
		if tokens.Valid {
			metadata.Tokens = &model.TokenUsage{
				TotalTokens: int(tokens.Int64),
			}
		}

		// Parse additional metadata from metadata_json
		if metadataJSON.Valid && metadataJSON.String != "" {
			var extraMetadata map[string]any
			if err := json.Unmarshal([]byte(metadataJSON.String), &extraMetadata); err == nil {
				metadata.Extra = make(map[string]string)
				for k, v := range extraMetadata {
					if str, ok := v.(string); ok {
						metadata.Extra[k] = str
					}
				}
			}
		}

		messages = append(messages, model.Message{
			UUID:      messageID.String,
			Timestamp: timestamp,
			Role:      role,
			Content:   contentBlocks,
			Metadata:  metadata,
		})
	}

	return messages, rows.Err()
}
